mapper.select:
SELECT  FROM tianquan_oauth.oauth_audit_inbox
WHERE tenant_id = #{tenantId} AND retain_until <= #{now}
  AND id > #{afterId} AND deleted_at IS NULL ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE tianquan_oauth.oauth_audit_inbox
SET state = #{po.state}, attempt_count = #{po.attemptCount}, next_attempt_at = #{po.nextAttemptAt}, claim_owner = #{po.claimOwner}, claim_token = #{po.claimToken}, claim_generation = #{po.claimGeneration}, lease_until = #{po.leaseUntil}, terminal_at = #{po.terminalAt}, failure_code = #{po.failureCode}, version = #{po.version}, update_user_id = #{po.updateUserId}, update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId} AND id = #{po.id} AND event_id = #{po.eventId}
  AND version = #{expectedVersion} AND deleted_at IS NULL

UPDATE tianquan_oauth.oauth_audit_inbox t
SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC', version = version + 1,
    update_time = #{now}, update_user_id = #{actor}
WHERE tenant_id = #{tenantId} AND id = #{id} AND version = #{expectedVersion}
  AND deleted_at IS NULL AND retain_until <= #{now}
  AND state IN ('STORED', 'DEAD', 'EXPIRED')
  AND NOT EXISTS (SELECT 1 FROM tianquan_oauth.oauth_audit_receipt r WHERE r.tenant_id = #{tenantId} AND r.inbox_pk = t.id AND r.deleted_at IS NULL)
  AND NOT EXISTS (SELECT 1 FROM tianquan_oauth.oauth_audit_dead_letter d WHERE d.tenant_id = #{tenantId} AND d.inbox_pk = t.id AND d.deleted_at IS NULL)
